#!/usr/bin/env bun
/**
 * build-index.ts — regenerate every generated file in a v2 design system.
 *
 *   1. tokens/tokens.json + tokens/TOKENS.md   (via export-tokens.ts)
 *   2. components/INDEX.md                     (from each spec's frontmatter)
 *   3. README.md, two generated sections:
 *        <!-- BEGIN GENERATED: file-index … -->  … <!-- END GENERATED: file-index -->
 *          a file tree with a one-line purpose per file
 *        <!-- BEGIN GENERATED: inventory … -->   … <!-- END GENERATED: inventory -->
 *          version + per-level ready/draft counts
 *      The BEGIN line is matched by prefix and preserved as written; only the
 *      lines between the markers are replaced. The older
 *      <!-- index:start --> / <!-- index:end --> pair is accepted for file-index.
 *      A README with no markers gets both sections appended.
 *
 * The README is the one file an agent opens first, so its index must never lie
 * about what is on disk. Rebuilding from the disk every time (rather than
 * editing by hand) is what keeps it true; verify-stage.ts warns when the block
 * drifts. Idempotent: running twice changes nothing the second time.
 *
 * Usage: bun build-index.ts --target <repo> [--json]
 * Exit:  0 ok (a tokens export skipped for unresolved placeholders is a warning)
 *        1 failures · 2 cannot run (no design-system/ root)
 */

import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join, relative, resolve } from "node:path";
import { exportTokens } from "./export-tokens.ts";

export const ROOT = "design-system";
export const LEVELS = ["atoms", "molecules", "organisms", "templates"] as const;

const GENERATED = "generated by scripts/build-index.ts — do not hand-edit";

export type Section = "file-index" | "inventory";
const SECTION_TITLE: Record<Section, string> = { "file-index": "Files", inventory: "Inventory" };
const LEGACY: Partial<Record<Section, [RegExp, string]>> = {
  "file-index": [/<!-- index:start -->/, "<!-- index:end -->"],
};

// ---------------------------------------------------------------------------
// Reference HTML helpers — shared with verify-stage.ts and grade-run.ts so the
// gate and the eval grader read specimen IDs the same way.
// ---------------------------------------------------------------------------

/**
 * Strip comments, <pre>/<code> and inline <svg> so documentation examples and
 * path data (which is full of things that look like IDs) aren't flagged.
 */
export function strippedOf(html: string): string {
  // Closing tags may carry whitespace or a newline before ">" (formatters wrap
  // them: "</code\n>"); a strict "</code>" never matched and the strip ate
  // everything up to some later </code>.
  return html
    .replace(/<!--[\s\S]*?-->/g, "")
    .replace(/<svg\b[\s\S]*?<\/svg\s*>/gi, "")
    .replace(/<pre\b[\s\S]*?<\/pre\s*>/gi, "")
    .replace(/<code\b[\s\S]*?<\/code\s*>/gi, "");
}

/**
 * Specimen IDs in order of first appearance, read ONLY from where an ID is
 * declared — an id="" or data-*="" attribute, or a .card-label — never from
 * prose, so "A-01 to A-12" in an intro paragraph is not an inventory.
 */
export function extractIds(html: string, prefix: string): string[] {
  const re = new RegExp(
    `\\s(?:id|data-[\\w-]+)\\s*=\\s*"(${prefix}-\\d+)"|class\\s*=\\s*"[^"]*\\bcard-label\\b[^"]*"[^>]*>\\s*(?:<[^>]+>\\s*)*(${prefix}-\\d+)\\b`,
    "g",
  );
  const out: string[] = [];
  for (const m of strippedOf(html).matchAll(re)) {
    const id = m[1] ?? m[2];
    if (!out.includes(id)) out.push(id);
  }
  return out;
}

// ---------------------------------------------------------------------------
// Frontmatter
// ---------------------------------------------------------------------------

export type Frontmatter = Record<string, string | string[]>;

/** A deliberately small YAML subset: scalars, [inline, lists] and "- item" lists. */
export function parseFrontmatter(md: string): Frontmatter | null {
  const m = md.match(/^﻿?---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) return null;
  const out: Frontmatter = {};
  let listKey: string | null = null;
  for (const raw of m[1].split(/\r?\n/)) {
    const item = raw.match(/^\s+-\s+(.*)$/);
    if (item && listKey) {
      (out[listKey] as string[]).push(unquote(item[1]));
      continue;
    }
    const kv = raw.match(/^([\w-]+):\s*(.*)$/);
    if (!kv) continue;
    const [, key, val] = kv;
    if (val === "") {
      out[key] = [];
      listKey = key;
    } else if (/^\[.*\]$/.test(val.trim())) {
      out[key] = val.trim().slice(1, -1).split(",").map((s) => unquote(s)).filter(Boolean);
      listKey = null;
    } else {
      out[key] = unquote(val);
      listKey = null;
    }
  }
  return out;
}

const unquote = (s: string) => s.trim().replace(/^["']|["']$/g, "");
const asList = (v: string | string[] | undefined) => (Array.isArray(v) ? v : v ? [v] : []);

/** First-column values of the table under the "States" heading. */
function statesFromBody(md: string): string[] {
  const sec = md.match(/^#{2,3}\s+States\b[^\n]*\n([\s\S]*?)(?=^#{1,3}\s|$(?![\s\S]))/m);
  if (!sec) return [];
  return (sec[1].match(/^\|[^\n]*\|\s*$/gm) ?? [])
    .map((r) => r.split("|")[1]?.trim() ?? "")
    .filter((c) => c && !/^[-:\s]+$/.test(c) && !/^state$/i.test(c))
    .map((c) => c.replace(/`/g, ""));
}

// ---------------------------------------------------------------------------
// Component specs
// ---------------------------------------------------------------------------

export interface Spec {
  id: string;
  name: string;
  level: string;
  status: string;
  composes: string[];
  states: string[];
  specimen: string;
  path: string; // relative to design-system/
  frontmatter: Frontmatter | null;
}

export function readSpecs(root: string): Spec[] {
  const specs: Spec[] = [];
  for (const level of LEVELS) {
    const dir = join(root, "components", level);
    if (!existsSync(dir)) continue;
    for (const f of readdirSync(dir).filter((f) => f.endsWith(".md")).sort()) {
      const md = readFileSync(join(dir, f), "utf8");
      const fm = parseFrontmatter(md);
      // icons.md is the one shared spec for the I-nn icon set on icons.html.
      const idFromName = f === "icons.md" ? "I-nn" : (f.match(/^([AMOT]-\d+)/)?.[1] ?? "");
      const states = asList(fm?.states);
      specs.push({
        id: (fm?.id as string) || idFromName,
        name: (fm?.name as string) || f.replace(/^[AMOT]-\d+-/, "").replace(/\.md$/, ""),
        level: (fm?.level as string) || level.replace(/s$/, ""),
        status: (fm?.status as string) || "draft",
        composes: asList(fm?.composes),
        states: states.length ? states : statesFromBody(md),
        specimen: (fm?.specimen as string) || "",
        path: `components/${level}/${f}`,
        frontmatter: fm,
      });
    }
  }
  const order = (s: Spec) => LEVELS.findIndex((l) => s.path.startsWith(`components/${l}/`));
  return specs.sort((a, b) => order(a) - order(b) || a.id.localeCompare(b.id, "en", { numeric: true }));
}

/** Only status: approved counts as ready; draft (and anything else) does not. */
const isReady = (s: Spec) => s.status === "approved";

/** The icon set's one shared spec — counted on its own row, never as an atom. */
const isIcons = (s: Spec) => s.path === "components/atoms/icons.md";
const atLevel = (specs: Spec[], level: string) => specs.filter((s) => s.path.startsWith(`components/${level}/`) && !isIcons(s));

/**
 * status: legacy = usable, built before v2, never signed off under it. Counted
 * on its own so a migrated system doesn't read as "0 ready" or as "all draft".
 */
const isLegacy = (s: Spec) => s.status === "legacy";

function countTable(specs: Spec[]): string[] {
  const rows = ["| Level | Ready | Draft | Legacy | Total |", "|---|---|---|---|---|"];
  const row = (label: string, at: Spec[]) =>
    rows.push(
      `| ${label} | ${at.filter(isReady).length} | ${at.filter((s) => s.status === "draft").length} | ${at.filter(isLegacy).length} | ${at.length} |`,
    );
  for (const level of LEVELS) {
    row(`${level[0].toUpperCase()}${level.slice(1)}`, atLevel(specs, level));
    if (level === "atoms") {
      const icons = specs.filter(isIcons);
      if (icons.length) row("Icons (set)", icons);
    }
  }
  return rows;
}

export function renderComponentIndex(allSpecs: Spec[], version: string): string {
  const icons = allSpecs.filter(isIcons);
  const specs = allSpecs.filter((s) => !isIcons(s));
  const ready = specs.filter(isReady);
  const lines = [
    `<!-- ${GENERATED} -->`,
    "",
    "# Component index",
    "",
    `Version ${version} · ${ready.length} ready / ${specs.filter((s) => s.status === "draft").length} draft / ${specs.filter(isLegacy).length} legacy / ${specs.length} total. Only \`status: approved\` counts as ready; \`legacy\` is usable but predates v2 sign-off; drafts may change. One spec file per ID.`,
    "",
    ...countTable(allSpecs),
    "",
  ];
  if (icons.length) {
    const s = icons[0];
    lines.push(
      "## Icons (set)",
      "",
      "One spec covers every I-nn icon on icons.html.",
      "",
      `| Spec | Status | Specimen |`,
      "|---|---|---|",
      `| [icons.md](atoms/icons.md) | ${s.status} | ${s.specimen ? `[${s.specimen.split("/").pop()}](../${s.specimen})` : "[icons.html](../reference/icons.html)"} |`,
      "",
    );
  }
  for (const level of LEVELS) {
    const rows = atLevel(specs, level);
    lines.push(`## ${level[0].toUpperCase()}${level.slice(1)} (${rows.length})`, "");
    if (!rows.length) {
      lines.push("_None yet._", "");
      continue;
    }
    lines.push("| ID | Name | Level | Status | Composes | States | Spec | Specimen |", "|---|---|---|---|---|---|---|---|");
    for (const s of rows) {
      lines.push(
        `| ${s.id} | ${s.name} | ${s.level} | ${s.status} | ${s.composes.join(", ") || "—"} | ${s.states.join(", ") || "—"} | [${s.path.split("/").pop()}](${s.path.replace(/^components\//, "")}) | ${s.specimen ? `[${s.specimen.split("/").pop()}](../${s.specimen})` : "—"} |`,
      );
    }
    lines.push("");
  }
  return lines.join("\n");
}

// ---------------------------------------------------------------------------
// README file index
// ---------------------------------------------------------------------------

const PURPOSE: Record<string, string> = {
  "README.md": "START HERE — file index, how to consume the tokens, the non-negotiable rules",
  "STATE.json": "build state: schemaVersion, version, themes, stages, approvals, inventory",
  "CHANGELOG.md": "one entry per approved stage / publish (semver)",
  "brief/": "Stage 0 inputs",
  "brief/DESIGN-BRIEF.md": "brand contract, inspiration map (take + leave), recorded gaps",
  "tokens/": "design tokens",
  "tokens/tokens.css": "CANONICAL — the only file with raw values; tiers brand → alias → mapped → responsive",
  "tokens/tokens.json": "generated — W3C DTCG tokens, tiers + modes, aliases as {refs}",
  "tokens/TOKENS.md": "generated — one table per tier: value, other modes, resolved value, notes",
  "tokens/figma/": "optional Figma Variables export (scripts/export-figma.ts)",
  "tokens/figma/README.md": "how to import the collections into Figma",
  "foundations/": "foundation rules",
  "foundations/FOUNDATIONS.md": "colour, type, space, grid, shape, elevation, motion, accessibility rules",
  "components/": "one spec per component ID",
  "components/INDEX.md": "generated — every ID: name, level, status, composes, states, spec, specimen",
  "components/atoms/": "A-nn specs",
  "components/molecules/": "M-nn specs",
  "components/organisms/": "O-nn specs",
  "components/templates/": "T-nn specs",
  "rules/": "governance",
  "rules/RULES.md": "promotion ladder, ownership, guardrails, a11y floor, change protocol",
  "reference/": "human visual review site (static HTML, noindex)",
  "reference/styles.css": "imports ../tokens/tokens.css; chrome + specimen CSS; mapped tokens only",
  "reference/index.html": "00 · system map",
  "reference/foundations.html": "01 · foundations specimens",
  "reference/atoms.html": "02 · atom specimens",
  "reference/icons.html": "02A · icon set",
  "reference/molecules.html": "03 · molecule specimens",
  "reference/organisms.html": "04 · organism specimens",
  "reference/templates.html": "05 · template specimens",
  "reference/pages.html": "06 · page reference index",
  "reference/rules.html": "07 · rules, rendered",
  "reference/pages/": "one full-page reference per P-nn",
  "reference/snapshots/": "inspiration snapshots captured with Interceptor (Stage 0)",
};

/**
 * Directories listed as ONE line with a count rather than walked, so the README
 * stays ~150 lines however big the system grows. Component folders summarise
 * by status and point at components/INDEX.md, which lists every spec.
 */
const SUMMARISED = new Set([
  "reference/assets/",
  "reference/fonts/",
  "reference/pen/",
  "components/atoms/",
  "components/molecules/",
  "components/organisms/",
  "components/templates/",
  "reference/pages/",
  "reference/snapshots/",
  "tokens/figma/",
]);
const IGNORED = new Set([".DS_Store", "Thumbs.db", "node_modules", ".git", ".gitkeep"]);

function summaryOf(root: string, rel: string): string {
  const files = readdirSync(join(root, rel)).filter((f) => !IGNORED.has(f));
  if (rel.startsWith("components/")) {
    const specs = files.filter((f) => f.endsWith(".md"));
    const by = new Map<string, number>();
    for (const f of specs) {
      const st = (parseFrontmatter(readFileSync(join(root, rel, f), "utf8"))?.status as string) || "draft";
      by.set(st, (by.get(st) ?? 0) + 1);
    }
    const parts = [...by.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([s, n]) => `${n} ${s}`);
    return `(${specs.length} spec${specs.length === 1 ? "" : "s"}${parts.length ? `: ${parts.join(", ")}` : ""} — listed in components/INDEX.md)`;
  }
  return `(${files.length} file${files.length === 1 ? "" : "s"})`;
}

function purposeOf(root: string, rel: string): string {
  if (PURPOSE[rel]) return PURPOSE[rel];
  const abs = join(root, rel);
  if (/^components\/[a-z]+\/.+\.md$/.test(rel)) {
    const fm = parseFrontmatter(readFileSync(abs, "utf8"));
    const name = fm?.name as string | undefined;
    const status = fm?.status as string | undefined;
    return [name, status && status !== "approved" ? `(${status})` : ""].filter(Boolean).join(" ") || "component spec";
  }
  if (/^reference\/pages\/.+\.html$/.test(rel)) {
    const html = readFileSync(abs, "utf8");
    const id = html.match(/data-page="(P-\d+)"/)?.[1];
    const title = html.match(/<title>([^<·]*)/)?.[1]?.trim();
    return [id, title].filter(Boolean).join(" · ") || "page reference";
  }
  const figma = rel.match(/^tokens\/figma\/(.+)\.json$/);
  if (figma) return `Figma collection ${figma[1]} (DTCG)`;
  return "";
}

function walkTree(root: string, relDir = "", prefix = ""): string[] {
  const abs = join(root, relDir);
  const entries = readdirSync(abs)
    .filter((e) => !IGNORED.has(e))
    .map((e) => ({ e, dir: statSync(join(abs, e)).isDirectory() }))
    // Files before folders at each level, each alphabetical, README first at the root.
    .sort((a, b) =>
      a.dir !== b.dir ? (a.dir ? 1 : -1) : a.e === "README.md" ? -1 : b.e === "README.md" ? 1 : a.e.localeCompare(b.e, "en", { numeric: true }),
    );
  const lines: string[] = [];
  entries.forEach(({ e, dir }, i) => {
    const rel = `${relDir}${e}${dir ? "/" : ""}`;
    const last = i === entries.length - 1;
    const branch = last ? "└── " : "├── ";
    let label = `${e}${dir ? "/" : ""}`;
    if (SUMMARISED.has(rel)) label += ` ${summaryOf(root, rel)}`;
    const p = purposeOf(root, rel);
    lines.push(`${prefix}${branch}${label}${p ? ` — ${p}` : ""}`);
    if (dir && !SUMMARISED.has(rel)) lines.push(...walkTree(root, rel, prefix + (last ? "    " : "│   ")));
  });
  return lines;
}

/** File-index section body: a fenced tree with one purpose per line. */
export function renderFileIndex(root: string): string {
  return ["```text", "design-system/", ...walkTree(root), "```"].join("\n");
}

export function readVersion(root: string): string {
  try {
    return JSON.parse(readFileSync(join(root, "STATE.json"), "utf8")).version ?? "0.0.0";
  } catch {
    return "0.0.0";
  }
}

/** Inventory section body: version + per-level ready/draft counts + page refs. */
export function renderInventory(root: string, specs = readSpecs(root)): string {
  const pagesDir = join(root, "reference", "pages");
  const pages = existsSync(pagesDir) ? readdirSync(pagesDir).filter((f) => f.endsWith(".html")).length : 0;
  const components = specs.filter((s) => !isIcons(s));
  const iconSet = specs.some(isIcons) ? " · icon set spec" : "";
  return [
    `Version **${readVersion(root)}** · ${components.filter(isReady).length} ready / ${components.filter((s) => s.status === "draft").length} draft / ${components.filter(isLegacy).length} legacy / ${components.length} component spec(s)${iconSet} · ${pages} page reference(s)`,
    "",
    ...countTable(specs),
  ].join("\n");
}

interface Found {
  /** Index just after the BEGIN marker. */
  innerStart: number;
  /** Index of the END marker. */
  innerEnd: number;
}

function markerPairs(section: Section): [RegExp, string][] {
  const pairs: [RegExp, string][] = [
    [new RegExp(`<!--\\s*BEGIN GENERATED:\\s*${section}\\b[\\s\\S]*?-->`), `<!-- END GENERATED: ${section} -->`],
  ];
  const legacy = LEGACY[section];
  if (legacy) pairs.push(legacy);
  return pairs;
}

/** Locate a generated section. BEGIN is matched by prefix through the next "-->". */
export function findSection(readme: string, section: Section): Found | null {
  for (const [begin, end] of markerPairs(section)) {
    const m = begin.exec(readme);
    if (!m) continue;
    const afterBegin = m.index + m[0].length;
    const e = readme.indexOf(end, afterBegin);
    if (e === -1) continue;
    return { innerStart: afterBegin, innerEnd: e };
  }
  return null;
}

/**
 * A BEGIN marker with no END after it. Rewriting would either append a second
 * section or eat everything after BEGIN — both destroy hand-written text — so
 * the caller must stop and let a human fix the marker.
 */
export function brokenMarker(readme: string, section: Section): string | null {
  for (const [begin, end] of markerPairs(section)) {
    const m = begin.exec(readme);
    if (m && readme.indexOf(end, m.index + m[0].length) === -1) {
      return `README.md has a BEGIN marker for "${section}" but no "${end}" after it`;
    }
  }
  return null;
}

/** Current body of a section, trimmed; null when the markers are absent. */
export function currentSection(readme: string, section: Section): string | null {
  const f = findSection(readme, section);
  return f ? readme.slice(f.innerStart, f.innerEnd).trim() : null;
}

/** Replace only the lines between the markers; the BEGIN line is kept as written. */
export function spliceSection(readme: string, section: Section, body: string): string {
  const broken = brokenMarker(readme, section);
  if (broken) throw new Error(broken);
  const f = findSection(readme, section);
  if (f) return `${readme.slice(0, f.innerStart)}\n${body}\n${readme.slice(f.innerEnd)}`;
  return (
    `${readme.replace(/\s*$/, "")}\n\n## ${SECTION_TITLE[section]}\n\n` +
    `<!-- BEGIN GENERATED: ${section} — scripts/build-index.ts, do not hand-edit -->\n${body}\n<!-- END GENERATED: ${section} -->\n`
  );
}

/** What each README section should contain right now — verify-stage compares against it. */
export function expectedReadmeSections(root: string): Record<Section, string> {
  return { "file-index": renderFileIndex(root), inventory: renderInventory(root) };
}

// ---------------------------------------------------------------------------
// CLI
// ---------------------------------------------------------------------------

if (import.meta.main) {
  const argv = process.argv.slice(2);
  const i = argv.indexOf("--target");
  const repo = resolve(i !== -1 && argv[i + 1] ? argv[i + 1] : process.cwd());
  const root = join(repo, ROOT);
  const asJson = argv.includes("--json");

  if (!existsSync(join(root, "STATE.json"))) {
    console.error(`✗ No ${ROOT}/STATE.json under ${repo} — build-index is for v2 systems. Run init-system.ts first.`);
    process.exit(2);
  }

  const messages: string[] = [];
  const warnings: string[] = [];
  let failed = false;

  // 1. Tokens. Unresolved placeholders before Stage 1 are expected, not a failure.
  const tok = exportTokens(repo);
  if (tok.code === 0) messages.push(...tok.messages);
  else if (tok.code === 1 && /placeholder/.test(tok.messages.join(" "))) warnings.push(`tokens export skipped: ${tok.messages.join(" ").replace(/^✗ /, "")}`);
  else {
    failed = true;
    messages.push(...tok.messages);
  }

  // 2. Component index.
  const specs = readSpecs(root);
  const indexPath = join(root, "components", "INDEX.md");
  const indexMd = renderComponentIndex(specs, readVersion(root));
  const prevIndex = existsSync(indexPath) ? readFileSync(indexPath, "utf8") : null;
  if (prevIndex !== indexMd) writeFileSync(indexPath, indexMd);
  messages.push(`✓ components/INDEX.md — ${specs.length} spec(s)${prevIndex === indexMd ? " (unchanged)" : ""}`);

  // 3. README sections. Written last so the tree includes the files above.
  const readmePath = join(root, "README.md");
  if (!existsSync(readmePath)) writeFileSync(readmePath, `# Design system\n`); // so the tree lists it
  const raw = readFileSync(readmePath, "utf8");
  const crlf = raw.includes("\r\n");
  const readme = raw.replace(/\r\n/g, "\n");
  const sections = Object.entries(expectedReadmeSections(root)) as [Section, string][];
  const broken = sections.map(([s]) => brokenMarker(readme, s)).filter(Boolean) as string[];
  if (broken.length) {
    failed = true;
    for (const b of broken) messages.push(`✗ ${b} — README left untouched; restore the END marker and re-run.`);
  } else {
    let next = readme;
    for (const [section, body] of sections) next = spliceSection(next, section, body);
    // Keep the file's own line endings so a Windows checkout doesn't churn.
    if (next !== readme) writeFileSync(readmePath, crlf ? next.replace(/\n/g, "\r\n") : next);
    messages.push(`✓ README.md file-index + inventory${next === readme ? " (unchanged)" : " rewritten"}`);
  }

  if (asJson) {
    console.log(JSON.stringify({ target: repo, ok: !failed, messages, warnings, specs: specs.length }, null, 2));
  } else {
    for (const m of messages) console.log(m);
    for (const w of warnings) console.log(`⚠ ${w}`);
  }
  process.exit(failed ? 1 : 0);
}
